[CmdletBinding()]
param([Parameter(Mandatory)][string]$PlanPath,[Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference = 'Stop'
$plan = Get-Content -LiteralPath ([IO.Path]::GetFullPath($PlanPath)) -Raw -Encoding UTF8 | ConvertFrom-Json
$payload = $plan | ConvertTo-Json -Depth 100 -Compress
# script 元素是 raw-text；将 < 和 > 编码为 JSON Unicode escape，避免计划内容关闭 script 标签。
$safePayload = $payload.Replace('&', ([string][char]92) + 'u0026').Replace(([string][char]60), ([string][char]92) + 'u003c').Replace(([string][char]62), ([string][char]92) + 'u003e').Replace(([string][char]0x2028), ([string][char]92) + 'u2028').Replace(([string][char]0x2029), ([string][char]92) + 'u2029')
$title = [System.Net.WebUtility]::HtmlEncode([string]$plan.title)
$html = @"
<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Plan Approval - $title</title>
<style>
:root{color-scheme:light;--bg:#f4f6fa;--panel:#fff;--text:#1f2937;--muted:#667085;--line:#d9e0ea;--accent:#4f46e5;--ok:#087443;--ok-bg:#e7f6ee;--warn:#9a6700;--warn-bg:#fff4d6;--danger:#b42318;--danger-bg:#ffebe9;--info-bg:#eef2ff;--shadow:0 8px 24px rgba(16,24,40,.06)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}button,input,textarea{font:inherit}button{cursor:pointer;border:1px solid var(--line);border-radius:7px;padding:8px 12px;background:var(--panel);color:var(--text)}button:hover{border-color:var(--accent)}button.primary{background:var(--accent);border-color:var(--accent);color:#fff}button.ok{background:var(--ok);border-color:var(--ok);color:#fff}button.warn{background:var(--warn);border-color:var(--warn);color:#fff}button.danger{background:var(--danger);border-color:var(--danger);color:#fff}button.small{padding:5px 8px;font-size:12px}input,textarea{width:100%;border:1px solid var(--line);border-radius:7px;padding:8px;background:#fff;color:var(--text)}textarea{resize:vertical}.shell{display:grid;grid-template-columns:252px minmax(0,1fr);min-height:100vh}.sidebar{position:sticky;top:0;height:100vh;overflow:auto;background:#182230;color:#eef2f7;padding:20px 14px}.brand{font-size:18px;font-weight:750;margin:0 8px 4px}.subbrand{font-size:12px;color:#aab7c8;margin:0 8px 18px;word-break:break-all}.nav-title{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#94a3b8;padding:10px 8px 6px}.nav a{display:flex;align-items:center;gap:8px;padding:8px;border-radius:6px;color:#cbd5e1;text-decoration:none}.nav a:hover,.nav a.active{background:#2b3b51;color:#fff}.nav .count{margin-left:auto;font-size:11px;color:#aab7c8}.main{min-width:0;padding:28px clamp(18px,4vw,52px) 120px}.hero{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:18px}.hero h1{margin:0 0 6px;font-size:28px;line-height:1.2}.meta{color:var(--muted);font-size:12px;word-break:break-word}.status{display:inline-flex;align-items:center;gap:6px;border-radius:99px;padding:5px 10px;background:var(--warn-bg);color:var(--warn);font-weight:700;white-space:nowrap}.progress-wrap{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:14px;margin-bottom:18px;box-shadow:var(--shadow)}.progress-line{height:8px;background:#e7ebf2;border-radius:99px;overflow:hidden}.progress-bar{height:100%;width:0;background:var(--accent);transition:width .2s}.progress-text{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin-bottom:8px}.section{scroll-margin-top:18px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:20px;margin:16px 0;box-shadow:var(--shadow)}.section h2{font-size:19px;margin:0 0 4px}.section-note{color:var(--muted);font-size:12px;margin:0 0 14px}.section>h2{cursor:pointer}.section.collapsed>h2:before{content:'▶ ';font-size:12px;color:var(--muted)}.section:not(.collapsed)>h2:before{content:'▼ ';font-size:12px;color:var(--muted)}.section.collapsed>*:not(h2){display:none}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}.field{border:1px solid var(--line);border-radius:9px;padding:11px;background:#fbfcfe}.field-label{font-size:11px;font-weight:700;color:var(--muted);margin-bottom:4px}.field-value{white-space:pre-wrap;overflow-wrap:anywhere}.item-list{display:grid;gap:12px}.card{border:1px solid var(--line);border-radius:10px;padding:14px;background:#fff}.card-header{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.card-title{font-weight:750}.tag{display:inline-block;border-radius:99px;padding:2px 7px;font-size:11px;font-weight:700;background:var(--info-bg);color:#3730a3;margin-right:6px}.tag.ok{background:var(--ok-bg);color:var(--ok)}.tag.warn{background:var(--warn-bg);color:var(--warn)}.tag.danger{background:var(--danger-bg);color:var(--danger)}.card-body{margin-top:10px}.card-actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}.decision-card{border-left:4px solid #7c5cff}.decision-card.resolved{border-left-color:var(--ok)}.decision-card.rejected{border-left-color:var(--danger)}.decision-state{font-size:12px;font-weight:700;color:var(--muted)}details.raw{margin-top:10px}details.raw summary{cursor:pointer;color:var(--muted);font-size:12px}pre{white-space:pre-wrap;overflow:auto;background:#f3f5f8;border-radius:7px;padding:10px;font:12px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace;margin:8px 0 0}.sticky-actions{position:fixed;bottom:0;left:252px;right:0;background:rgba(255,255,255,.96);backdrop-filter:blur(8px);border-top:1px solid var(--line);padding:12px clamp(18px,4vw,52px);display:flex;align-items:center;gap:8px;flex-wrap:wrap;z-index:5}.sticky-actions .hint{color:var(--muted);font-size:12px;margin-right:auto}.empty{color:var(--muted);padding:12px;border:1px dashed var(--line);border-radius:8px}.footer-note{color:var(--muted);font-size:12px;margin-top:18px}@media(max-width:800px){.shell{display:block}.sidebar{position:sticky;height:auto;z-index:4;padding:10px 12px}.brand,.subbrand{display:inline;margin:0 8px}.subbrand{font-size:11px}.nav-title{display:none}.nav{display:flex;overflow-x:auto;gap:4px;margin-top:8px}.nav a{white-space:nowrap;font-size:12px}.nav .count{display:none}.main{padding:18px 12px 150px}.hero{display:block}.hero .status{margin-top:12px}.sticky-actions{left:0;padding:10px 12px}}
</style>
</head>
<body>
<div class="shell">
<aside class="sidebar"><h1 class="brand">计划审批</h1><p class="subbrand" id="side-id"></p><nav class="nav" id="nav"></nav></aside>
<main class="main">
<header class="hero"><div><h1 id="title"></h1><div class="meta" id="meta"></div></div><span class="status" id="status">READY_FOR_APPROVAL</span></header>
<div class="progress-wrap"><div class="progress-text"><span>人工决策处理进度</span><span id="progress-text">0 / 0</span></div><div class="progress-line"><div class="progress-bar" id="progress-bar"></div></div></div>
<div id="content"></div>
<p class="footer-note">本页面由 task-spec 脚本生成。审批按钮只生成 approval-input.json，不会直接修改本地 approval.json；请将导出的文件交给 AI 导入。</p>
</main>
</div>
<div class="sticky-actions"><span class="hint" id="action-hint">先查看并处理必要的人工决策。</span><label style="width:180px"><input id="actor" placeholder="审批人" aria-label="审批人"></label><button class="ok" data-action="APPROVED">批准计划</button><button class="danger" data-action="REJECTED">驳回计划</button><button class="warn" data-action="CHANGES_REQUESTED">提交修改意见</button><button class="small" id="approve-all">全部确认人工决策</button><textarea id="overall-comment" rows="1" style="max-width:260px" placeholder="总体说明"></textarea><textarea id="output" rows="2" style="display:none"></textarea></div>
<script id="plan-data" type="application/json">$safePayload</script>
<script>
(function(){
'use strict';
const plan=JSON.parse(document.getElementById('plan-data').textContent);
const navItems=[['summary','需求摘要'],['current','当前行为'],['target','目标行为'],['facts','代码事实'],['inferences','推断'],['behavior','行为规则'],['scope','范围'],['technical','技术方案'],['references','参考代码'],['packages','执行包'],['risks','风险'],['acceptance','Acceptance Criteria'],['decisions','人工决策'],['audit','审批信息']];
const escText=function(value){if(value===null||value===undefined||value===''){return '未提供';}if(typeof value==='string'){return value;}return JSON.stringify(value,null,2);};
const labelize=function(key){return String(key).replace(/_/g,' ');};
const make=function(tag,className,text){const el=document.createElement(tag);if(className){el.className=className;}if(text!==undefined){el.textContent=text;}return el;};
const rawDetails=function(value){const details=make('details','raw');details.appendChild(make('summary','', '查看原始 JSON'));const pre=make('pre','',JSON.stringify(value,null,2));details.appendChild(pre);return details;};
const fields=function(value){const box=make('div','grid');if(value===null||value===undefined){box.appendChild(make('div','empty','未提供'));return box;}if(typeof value!=='object'){box.appendChild(make('div','field',''));box.firstChild.appendChild(make('div','field-value',''+escText(value)));return box;}Object.keys(value).forEach(function(key){const item=make('div','field');item.appendChild(make('div','field-label',labelize(key)));item.appendChild(make('div','field-value',escText(value[key])));box.appendChild(item);});return box;};
const listCards=function(list,kind){const box=make('div','item-list');if(!Array.isArray(list)||list.length===0){box.appendChild(make('div','empty','无'));return box;}list.forEach(function(item,index){const card=make('article','card');const header=make('div','card-header');const title=make('div','card-title');if(item&&item.id){title.appendChild(make('span','tag',item.id));}title.appendChild(make('span','tag',kind));title.appendChild(make('span','',item&& (item.title||item.name||item.question||item.text) ? (item.title||item.name||item.question||item.text) : kind+' '+(index+1)));header.appendChild(title);card.appendChild(header);card.appendChild(make('div','card-body')).appendChild(fields(item));card.appendChild(rawDetails(item));box.appendChild(card);});return box;};
const sections={summary:{title:'需求摘要',note:'需求目标、问题、价值与复杂度',value:plan.summary},current:{title:'当前行为',note:'基于代码事实的当前状态',value:plan.current_state},target:{title:'目标行为',note:'明确需求与基于事实的推断',value:plan.target_state},facts:{title:'代码事实',note:'代码观察、证据和当前约束',value:plan.current_state&&plan.current_state.facts?plan.current_state.facts:(plan.facts||plan.business_rules)},inferences:{title:'推断',note:'由事实推导的实现判断',value:plan.inferences||(plan.target_state&&plan.target_state.inferences)||(plan.target_state&&plan.target_state.inferred_behavior)},behavior:{title:'行为规则',note:'正常、失败、重复和边界场景',value:plan.behavior},scope:{title:'范围',note:'In Scope、Out of Scope 与实施边界',value:plan.scope},technical:{title:'技术方案',note:'技术方向、方案对比和依赖关系',value:plan.technical_direction},references:{title:'参考代码',note:'相似原因、复用边界、遗留与架构适配性',value:plan.reference_code_assessment},packages:{title:'执行包',note:'按依赖顺序执行的任务包、manifest、边界与契约',value:plan.packages},risks:{title:'风险',note:'风险等级、影响和缓解/验证措施',value:plan.risks},acceptance:{title:'Acceptance Criteria',note:'可由 Review 验证的最终可观察结果',value:plan.acceptance_criteria}};
const nav=document.getElementById('nav');navItems.forEach(function(entry){const a=document.createElement('a');a.href='#section-'+entry[0];a.dataset.target=entry[0];a.appendChild(make('span','',entry[1]));if(entry[0]==='decisions'){const count=Array.isArray(plan.open_decisions)?plan.open_decisions.filter(function(x){return x.resolution==='user-required';}).length:0;a.appendChild(make('span','count',String(count)));}nav.appendChild(a);});
const content=document.getElementById('content');Object.keys(sections).forEach(function(key){const section=sections[key];const el=make('section','section');el.id='section-'+key;const heading=make('h2','',section.title);heading.onclick=function(){el.classList.toggle('collapsed');};el.appendChild(heading);el.appendChild(make('p','section-note',section.note));if(Array.isArray(section.value)){el.appendChild(listCards(section.value,key));}else{el.appendChild(fields(section.value));el.appendChild(rawDetails(section.value));}content.appendChild(el);});
const decisionSection=make('section','section');decisionSection.id='section-decisions';decisionSection.appendChild(make('h2','','人工决策'));decisionSection.appendChild(make('p','section-note','每个 user-required Decision 独立确认；完成后再执行计划级批准。auto-resolved 项仅展示，不占用审批。'));const decisionBox=make('div','item-list');decisionSection.appendChild(decisionBox);content.appendChild(decisionSection);
const audit=make('section','section');audit.id='section-audit';audit.appendChild(make('h2','','审批信息'));audit.appendChild(make('p','section-note','计划身份、来源和完整结构用于审批脚本校验。'));audit.appendChild(fields({plan_package_id:plan.plan_package_id,package_revision:plan.package_revision,package_sha256:plan.plan_package_sha256,spec:plan.spec,status:plan.status}));audit.appendChild(rawDetails({plan_package_id:plan.plan_package_id,package_revision:plan.package_revision,package_sha256:plan.plan_package_sha256,spec:plan.spec,status:plan.status}));content.appendChild(audit);
document.getElementById('title').textContent=plan.title||plan.description||'未命名计划';document.getElementById('side-id').textContent=(plan.plan_package_id||'')+' · r'+plan.package_revision;document.getElementById('meta').textContent='Spec '+(plan.spec&&plan.spec.spec_id?plan.spec.spec_id:'未提供')+' · Package '+(plan.plan_package_id||'未提供')+' · SHA-256 '+(plan.plan_package_sha256||'未提供');
const decisions=Array.isArray(plan.open_decisions)?plan.open_decisions:[];const actionable=decisions.filter(function(item){return item.resolution==='user-required';});const itemDecisions={};
const decisionText=function(item){return {id:item.id,question:item.question||item.decision||item.text,options:item.options,recommendation:item.recommendation||item.planner_recommendation,user_decision:item.user_decision,resolution:item.resolution,blocking:item.blocking,source:item.source,based_on:item.based_on,impact:item.impact};};
const renderDecisions=function(){decisionBox.textContent='';if(decisions.length===0){decisionBox.appendChild(make('div','empty','没有需要人工决策的项目。'));}decisions.forEach(function(item){const card=make('article','card decision-card');const state=itemDecisions[item.id]?itemDecisions[item.id].decision:'PENDING';if(state==='APPROVED'){card.classList.add('resolved');}if(state==='REJECTED'){card.classList.add('rejected');}const header=make('div','card-header');const title=make('div','card-title');title.appendChild(make('span','tag',item.id||'D'));title.appendChild(make('span','tag',item.resolution||'auto-resolved'));title.appendChild(make('span','',item.question||item.decision||item.text||'未命名决策'));header.appendChild(title);header.appendChild(make('span','decision-state',state+(item.blocking?' · blocking':'')));card.appendChild(header);card.appendChild(make('div','card-body')).appendChild(fields(decisionText(item)));card.appendChild(rawDetails(item));if(item.resolution==='user-required'){const textarea=make('textarea','');textarea.rows=2;textarea.placeholder='该 Decision 的确认说明或修改意见';textarea.id='comment-'+item.id;card.appendChild(textarea);const actions=make('div','card-actions');[['APPROVED','确认/批准','ok'],['REJECTED','驳回','danger'],['CHANGES_REQUESTED','要求修改','warn']].forEach(function(buttonInfo){const button=make('button',buttonInfo[2],buttonInfo[1]);button.type='button';button.onclick=function(){const comment=document.getElementById('comment-'+item.id).value.trim();if(buttonInfo[0]!=='APPROVED'&&!comment){document.getElementById('action-hint').textContent='请先填写 '+item.id+' 的意见。';return;}itemDecisions[item.id]={id:item.id,kind:'decision',decision:buttonInfo[0],actor:document.getElementById('actor').value.trim(),comment:comment,decided_at:new Date().toISOString()};renderDecisions();};actions.appendChild(button);});card.appendChild(actions);}decisionBox.appendChild(card);});updateProgress();};
const updateProgress=function(){const total=actionable.length;const done=actionable.filter(function(item){return itemDecisions[item.id]&&itemDecisions[item.id].decision==='APPROVED';}).length;document.getElementById('progress-text').textContent=done+' / '+total;document.getElementById('progress-bar').style.width=(total?Math.round(done*100/total):100)+'%';document.getElementById('action-hint').textContent=total?'已确认 '+done+' / '+total+' 个必要人工决策。':'没有阻塞人工决策，可直接进行计划级审批。';};
const exportApproval=function(action){const actor=document.getElementById('actor').value.trim();if(!actor){document.getElementById('action-hint').textContent='请填写审批人。';return;}const feedback=[];Object.keys(itemDecisions).forEach(function(id){const item=itemDecisions[id];feedback.push({id:item.id,kind:'decision',comment:item.comment||'',decision:item.decision,actor:actor,decided_at:item.decided_at});});if(action==='APPROVED'){const blocked=actionable.filter(function(item){return item.blocking===true&&(!itemDecisions[item.id]||itemDecisions[item.id].decision!=='APPROVED');});if(blocked.length){document.getElementById('action-hint').textContent='仍有未确认的阻塞人工决策，不能批准计划。';return;}}const out={schema_version:'1.0',spec_id:plan.spec.spec_id,package_revision:plan.package_revision,package_sha256:plan.plan_package_sha256,decision:action,actor:actor,decided_at:new Date().toISOString(),statement:document.getElementById('overall-comment').value.trim(),item_decisions:feedback,item_feedback:feedback.map(function(item){return {id:item.id,comment:item.comment};})};const text=JSON.stringify(out,null,2);document.getElementById('output').value=text;const blob=new Blob([text],{type:'application/json'});const link=document.createElement('a');const url=URL.createObjectURL(blob);link.href=url;link.download='approval-input.json';link.click();setTimeout(function(){URL.revokeObjectURL(url);},0);document.getElementById('action-hint').textContent='已导出 approval-input.json，请把文件路径交给 AI 导入。';};
document.getElementById('approve-all').onclick=function(){const actor=document.getElementById('actor').value.trim();if(!actor){document.getElementById('action-hint').textContent='请填写审批人。';return;}actionable.forEach(function(item){itemDecisions[item.id]={id:item.id,kind:'decision',decision:'APPROVED',actor:actor,comment:'全部确认',decided_at:new Date().toISOString()};});renderDecisions();};document.querySelectorAll('button[data-action]').forEach(function(button){button.onclick=function(){exportApproval(button.dataset.action);};});
renderDecisions();
const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){document.querySelectorAll('.nav a').forEach(function(a){a.classList.toggle('active',a.dataset.target===entry.target.id.replace('section-',''));});}});},{rootMargin:'-15% 0px -70% 0px'});document.querySelectorAll('.section').forEach(function(section){observer.observe(section);});
})();
</script>
</body>
</html>
"@
$dir = Split-Path -Parent $OutputPath
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
[IO.File]::WriteAllText($OutputPath,$html,(New-Object Text.UTF8Encoding($false)))
